function formatDate(value) {
  if (!value) return '—';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return `${String(date.getDate()).padStart(2, '0')}/${String(date.getMonth() + 1).padStart(2, '0')}/${date.getFullYear()}`;
}

function formatDateTime(value) {
  if (!value) return '—';
  let date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    const normalized = String(value).trim().replace(/\./g, '-');
    const match = normalized.match(/^(\d{4})-(\d{1,2})-(\d{1,2})\s+(\d{1,2}):(\d{2})(?:\s*(AM|PM))?$/i);
    if (match) {
      const [, year, month, day, hourRaw, minute, ampmRaw] = match;
      let hour = parseInt(hourRaw, 10);
      const minutePadded = String(minute).padStart(2, '0');
      const ampm = (ampmRaw || '').toUpperCase();
      if (ampm === 'PM' && hour < 12) hour += 12;
      if (ampm === 'AM' && hour === 12) hour = 0;
      date = new Date(Number(year), Number(month) - 1, Number(day), hour, Number(minutePadded));
    }
  }

  if (Number.isNaN(date.getTime())) return value;
  let hour = date.getHours();
  const minute = String(date.getMinutes()).padStart(2, '0');
  const ampm = hour >= 12 ? 'PM' : 'AM';
  hour = hour % 12 || 12;
  const time = `${String(hour).padStart(2, '0')}:${minute} ${ampm}`;
  const dateStr = `${String(date.getDate()).padStart(2, '0')}/${String(date.getMonth() + 1).padStart(2, '0')}/${date.getFullYear()}`;
  return `${dateStr} ${time}`;
}

function parseMeetingDateTime(value) {
  const raw = String(value || '').trim();
  if (!raw) return { meeting_date: '', meeting_time: '10:00', meeting_ampm: 'AM' };

  const parts = raw.split(/\s+/);
  const datePart = parts[0] || '';
  let timePart = parts[1] || '';
  let ampm = (parts[2] || '').toUpperCase() || 'AM';

  if (/^(0?\d|1[0-2]):[0-5]\d$/.test(timePart) && /^(AM|PM)$/i.test(ampm)) {
    timePart = timePart.padStart(5, '0');
    ampm = ampm.toUpperCase();
  } else if (/^([01]?\d|2[0-3]):[0-5]\d$/.test(timePart)) {
    const [hourRaw, minute] = timePart.split(':').map(Number);
    ampm = hourRaw >= 12 ? 'PM' : 'AM';
    const displayHour = hourRaw % 12 || 12;
    timePart = `${String(displayHour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
  } else {
    timePart = '10:00';
    ampm = 'AM';
  }

  return {
    meeting_date: datePart,
    meeting_time: timePart,
    meeting_ampm: ampm,
  };
}

function buildMeetingDateTime(date, time, ampm) {
  if (!date || !time) return '';
  const [hourStr, minute] = time.split(':');
  let hour = parseInt(hourStr || '0', 10);
  if (Number.isNaN(hour)) return `${date} ${time}`;
  if (ampm === 'PM' && hour < 12) hour += 12;
  if (ampm === 'AM' && hour === 12) hour = 0;
  return `${date} ${String(hour).padStart(2, '0')}:${minute}`;
}

