  async function handleExport(format, selectedFields = null) {
    try {
      setExporting(true);
      if (typeof window.XLSX === 'undefined') return showToast('XLSX library not loaded', 'error');
      showToast('Preparing export...');

      let rows = (discussions || []).map((r) => ({
        'File No': r.file_no ?? '',
        'Date': formatDate(r.date),
        'Appointment': r.appointment ?? '',
        'Complaint': r.complaint ?? '',
        'Response': r.respond ?? '',
        'Meeting Date & Time': r.meeting_date_time ?? '',
        'Venue': r.venue ?? '',
        'Reminder Date': r.reminder_date ? formatDate(r.reminder_date) : '',
        'Reminder Notes': r.reminder_notes ?? '',
        'Officer': r.officer ?? '',
        'Status': r.status ?? '',
        'Created By': r.created_by ?? '',
        'Modified By': r.modified_by ?? '',
      }));

      if (selectedFields && selectedFields.length > 0) {
        rows = rows.map((r) => {
          const newRow = {};
          selectedFields.forEach((f) => {
            if (r[f] !== undefined) newRow[f] = r[f];
          });
          return newRow;
        });
      }

      if (format === 'pdf') {
        exportToPdfPrint('Discussions', rows);
        setExportModalOpen(false);
        showToast('PDF print dialog opened ✅');
        return;
      }

      const ws = window.XLSX.utils.json_to_sheet(rows);
      const wb = window.XLSX.utils.book_new();
      window.XLSX.utils.book_append_sheet(wb, ws, 'Discussions');
      window.XLSX.writeFile(wb, `CMA_Discussions_${new Date().toISOString().split('T')[0]}.xlsx`);
      setExportModalOpen(false);
      showToast('Exported ✅');
    } catch (err) {
      showToast(err.message || 'Export failed', 'error');
    } finally {
      setExporting(false);
    }
  }

